    private fun symbol(name: String, pathData: String): ImageVector =
        ImageVector.Builder(
            name = "Category.$name",
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 960f,
            viewportHeight = 960f,
        )
